func FlipCase(str string) string {
	var result strings.Builder
	result.Grow(len(str))

	for _, r := range str {
		if unicode.IsUpper(r) {
			result.WriteRune(unicode.ToLower(r))
		} else if unicode.IsLower(r) {
			result.WriteRune(unicode.ToUpper(r))
		} else {
			result.WriteRune(r)
